// Calcula huecos libres dentro del horario laboral (09:00-18:00)
// para la fecha consultada, restando los eventos ocupados.
const fecha = $('Preparar Ventana').first().json.fecha;
const INICIO_LABORAL = 9;   // 9:00
const FIN_LABORAL = 18;     // 18:00

const eventos = ($input.first().json.eventos || [])
  .filter(e => e && e.start && (e.start.dateTime || e.start.date))
  .map(e => {
    const ini = DateTime.fromISO(e.start.dateTime || e.start.date, { zone: 'America/Mexico_City' });
    const fin = DateTime.fromISO(e.end?.dateTime || e.end?.date || e.start.dateTime || e.start.date, { zone: 'America/Mexico_City' });
    return { titulo: e.summary || 'Sin título', ini, fin };
  })
  .sort((a, b) => a.ini - b.ini);

// Construye lista de huecos libres entre eventos, dentro del horario laboral
const libres = [];
let cursor = DateTime.fromISO(`${fecha}T${String(INICIO_LABORAL).padStart(2,'0')}:00:00`, { zone: 'America/Mexico_City' });
const finDia = DateTime.fromISO(`${fecha}T${String(FIN_LABORAL).padStart(2,'0')}:00:00`, { zone: 'America/Mexico_City' });

for (const ev of eventos) {
  if (ev.ini > cursor) {
    libres.push({ desde: cursor.toFormat('HH:mm'), hasta: ev.ini.toFormat('HH:mm') });
  }
  if (ev.fin > cursor) cursor = ev.fin;
}
if (cursor < finDia) {
  libres.push({ desde: cursor.toFormat('HH:mm'), hasta: finDia.toFormat('HH:mm') });
}

const ocupadosTxt = eventos.length === 0
  ? 'Sin eventos ese día.'
  : eventos.map(e => `• ${e.ini.toFormat('HH:mm')}–${e.fin.toFormat('HH:mm')} ${e.titulo}`).join('\n');

const libresTxt = libres.length === 0
  ? 'No hay huecos libres en horario laboral.'
  : libres.map(h => `• ${h.desde}–${h.hasta}`).join('\n');

const resultado = `📆 Disponibilidad para ${fecha} (horario 09:00–18:00):\n\nOcupado:\n${ocupadosTxt}\n\nLibre:\n${libresTxt}`;

return [{ json: { resultado, fecha, libres } }];
